import{c as t,Q as a,j as s,m as l}from"./chunks/framework.DOi4mjdC.js";const o="/assets/AllocMessage%E7%A4%BA%E6%84%8F%E5%9B%BE.DcNdz01I.png",g=JSON.parse('{"title":"AllocMessage","description":"","frontmatter":{},"headers":[{"level":1,"title":"AllocMessage","slug":"allocmessage"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Cube分组管理（ISASI）/CubeResGroupHandle/AllocMessage.md","filePath":"api/SIMD-API/基础API/Cube分组管理（ISASI）/CubeResGroupHandle/AllocMessage.md"}'),d={name:"api/SIMD-API/基础API/Cube分组管理（ISASI）/CubeResGroupHandle/AllocMessage.md"};function r(n,e,i,p,c,h){return a(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="allocmessage" tabindex="-1">AllocMessage <a class="header-anchor" href="#allocmessage" aria-label="Permalink to &quot;AllocMessage&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>AIV从消息队列里申请消息空间，用于存放消息结构体，返回当前申请的消息空间的地址。消息队列的深度固定为4，申请消息空间的顺序为自上而下，然后循环。当消息队列指针指向的消息空间为FREE状态时，AllocMessage返回空间的地址，否则循环等待，直到当前空间的状态为FREE。</p><p><strong>图 1</strong> AllocMessage示意图<br><img src="'+o+`" alt="" title="AllocMessage示意图"></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;PipeMode pipeMode = PipeMode::SCALAR_MODE&gt;             </span></span>
<span class="line"><span>__aicore__ inline __gm__ CubeMsgType *AllocMessage()</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>pipeMode</td><td>用于配置发送消息的执行单元。PipeMode类型，其定义如下： &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen11132212171216&quot;&gt;enum class PipeMode : uint8_t { SCALAR_MODE = 0, // Scalar执行单元往GM上写消息。 MTE3_MODE = 1, // 使用MTE3单元往GM上写消息。 MAX }&lt;/pre&gt; 注意，pipeMode为MTE3_MODE时，后续只能使用PostMessage接口发送消息。同时两个接口AllocMessage与PostMessage的模板参数pipeMode需要相同。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>当前申请的消息空间的地址。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto queIdx = AscendC::GetBlockIdx();</span></span>
<span class="line"><span>handle.AssignQueue(queIdx);</span></span>
<span class="line"><span>auto msgPtr = handle.AllocMessage();        // 绑定队列后，从该队列中申请消息空间，消息空间地址为msgPtr。</span></span></code></pre></div>`,17)])])}const A=t(d,[["render",r]]);export{g as __pageData,A as default};
